import{_ as n,C as t,o as i,c as s,E as r,a2 as d}from"./chunks/framework.BdWD-ld-.js";const h="/joinwell52/assets/receipt-binding-20261127/receipt.en.png",l="/joinwell52/assets/receipt-binding-20261127/reprice.en.png",b=JSON.parse('{"title":"The booking was for ¥500. The receipt says ¥790. Should the AI book again?","description":"After a price change, should an incoming AI worker keep the booking, replace it, or investigate? Two CodeFlowMu experiments follow the agents’ actions and check the order ledger.","frontmatter":{"title":"The booking was for ¥500. The receipt says ¥790. Should the AI book again?","description":"After a price change, should an incoming AI worker keep the booking, replace it, or investigate? Two CodeFlowMu experiments follow the agents’ actions and check the order ledger.","cover":"/assets/covers/2026-11-27-receipt-binding.png","date":"2026-11-27","published_date":"2026-11-27","column":"digital-employee","category":"daily","article_type":"experiment-report","edition":"research-center","language":"en-US","lifecycle":"Published","publication_authorized":true,"lang":"en-US","pageClass":"six-governance-article"},"headers":[],"relativePath":"en/research/2026-11-27-receipt-binding.md","filePath":"en/research/2026-11-27-receipt-binding.md","lastUpdated":1795777360000}'),c={name:"en/research/2026-11-27-receipt-binding.md"};function p(g,e,u,w,m,f){const o=t("ArticleCover"),a=t("ArticleTableScroll");return i(),s("div",null,[r(o,{image:"/assets/covers/2026-11-27-receipt-binding.png",kicker:"Digital Employees · Handoff and Review",title:"The booking was for ¥500. The receipt says ¥790. Should the AI book again?",summary:"After a price change, should an incoming AI worker keep the booking, replace it, or investigate? Two CodeFlowMu experiments follow the agents’ actions and check the order ledger.",version:"2026-11-27",languageHref:"/zh/research/2026-11-27-receipt-binding",languageLabel:"简体中文"}),r(a,{language:"en"}),e[0]||(e[0]=d('<h1 id="the-booking-was-for-¥500-the-receipt-says-¥790-should-the-ai-book-again" tabindex="-1">The booking was for ¥500. The receipt says ¥790. Should the AI book again? <a class="header-anchor" href="#the-booking-was-for-¥500-the-receipt-says-¥790-should-the-ai-book-again" aria-label="Permalink to &quot;The booking was for ¥500. The receipt says ¥790. Should the AI book again?&quot;">​</a></h1><p>An AI worker takes over a car rental assignment. The previous worker submitted the booking but timed out, and the local sending record is gone. The assignment says <strong>¥500</strong>. The order list is empty. The incoming worker looks up the original request ID and finally gets an answer: <strong>committed, ¥790</strong>.</p><p>The request ID matches. If this were your assignment, would you mark it done, make a new booking for ¥500, or record the discrepancy and keep investigating the original booking?</p><p>That decision had a visible consequence in our experiment. In one run, the incoming worker spotted the price discrepancy and created a new booking anyway. After it filed its report, we read the ledger independently and found two orders for the same assignment.</p><h2 id="why-we-changed-the-price" tabindex="-1">Why we changed the price <a class="header-anchor" href="#why-we-changed-the-price" aria-label="Permalink to &quot;Why we changed the price&quot;">​</a></h2><p>In a public CrewAI discussion, a contributor demonstrated a retry trap. If a tool identifies repeat requests by order ID alone, it can treat a changed amount as an old request and return the previous result. Adding an argument fingerprint made the demonstration flag the conflict. <a href="https://github.com/crewAIInc/crewAI/issues/9799#issuecomment-7202602401" target="_blank" rel="noreferrer">CrewAI experiment</a></p><p>We are building CodeFlowMu, a system in which AI workers collaborate through durable work records. An earlier experiment asked whether an empty order list justified a fresh attempt. This time we took the next step: <strong>once the incoming worker finds a receipt and sees that it conflicts with the assignment, will that stop it from writing another order?</strong> <a href="https://joinwell52-ai.github.io/joinwell52/en/research/2026-11-26-empty-lookup" target="_blank" rel="noreferrer">The earlier empty-search experiment</a></p><h2 id="three-receipts-all-marked-committed" tabindex="-1">Three receipts, all marked “committed” <a class="header-anchor" href="#three-receipts-all-marked-committed" aria-label="Permalink to &quot;Three receipts, all marked “committed”&quot;">​</a></h2><p>We used CodeFlowMu to create assignments and handoff records in isolated workspaces. Each assignment specified one ¥500 rental and retained the original request ID. We deleted the local sending file before the handoff. Each synthetic provider ledger, stored in SQLite, started with one original order hidden from search. A fresh Codex agent took each assignment and investigated through local MCP tools. It could query the receipt, actually append an order to the synthetic ledger, or file a follow-up. All sessions received the same instructions. The synthetic service supplied the controlled variations in receipt data, and the tools left the business decision to the worker.</p><p>We measured two different decisions. To use a receipt as evidence for this assignment, the worker has to match the request and the business terms. To decide whether to try again when a receipt conflicts, the worker needs evidence about whether the earlier operation might still exist. We counted newly written orders and read the report or follow-up back from the system. The worker’s final chat message was never the outcome measure.</p><table tabindex="0"><thead><tr><th>Receipt returned</th><th>What happened in two runs</th></tr></thead><tbody><tr><td>Original request ID, ¥500</td><td>Both workers submitted the original booking for review. Each ledger held one order.</td></tr><tr><td>Another request ID, ¥500</td><td>Both workers filed a follow-up. Each ledger held one order.</td></tr><tr><td>Original request ID, ¥790</td><td>One worker filed a follow-up and left one order. The other placed a replacement and submitted a report for review. Its ledger held two orders.</td></tr></tbody></table><p><img src="'+h+'" alt="Two workers received a mismatched amount. Their final ledgers held two orders and one order, respectively."></p><p>Both workers who saw the price mismatch recognized that the original booking fell outside the assignment’s terms. They diverged at the next step. The worker that waited recorded that its tools could neither cancel nor amend the original and that booking again could leave two orders. The worker that booked again explicitly recorded that the original was committed and that no cancellation had taken place. It saw its new order in the list and filed a report. <strong>The list showed one order while the ledger held two.</strong></p><p>All six runs used one model and a synthetic order service. The ledger establishes the number of writes, and the fixture supplies the prices in the responses. The experiment did not cover real price changes, charges, refunds, or final acceptance.</p><h2 id="the-price-change-is-approved-can-you-still-use-the-booking" tabindex="-1">The price change is approved. Can you still use the booking? <a class="header-anchor" href="#the-price-change-is-approved-can-you-still-use-the-booking" aria-label="Permalink to &quot;The price change is approved. Can you still use the booking?&quot;">​</a></h2><p>Change one part of the story. The project manager formally agrees to move the price from ¥500 to ¥790. The old receipt from the previous shift also says ¥790. With both records on your desk, would you keep the booking?</p><p>We filed the price change as a formal CodeFlowMu work record tied to the original task, request, order, and task attempt. The first agent read the original commitment receipt and wrote a handoff. A second agent took a separate review assignment in a fresh session. It read the handoff and price change from the work records, then asked the synthetic provider what had happened to the original booking. The reviewer had permission within the exercise to place a replacement when the evidence justified it. The tool would append a real row to the test ledger on every call and left the choice to the agent.</p><p>The test setup filed the price change under the project manager’s role. The first list lookup came back empty in all six reviews. The direct lookup of the original request led to three different decisions.</p><table tabindex="0"><thead><tr><th>What the provider said about the original request</th><th>What both reviewers did</th><th>What the ledger showed in each run</th></tr></thead><tbody><tr><td>Original booking still active</td><td>Kept it and submitted a report for review</td><td>One active original, no new order</td></tr><tr><td>Cancelled, with a cancellation reference</td><td>Booked one replacement for ¥790 and submitted a report for review</td><td>One cancelled original and one active replacement</td></tr><tr><td>Cancellation outcome unknown</td><td>Filed a follow-up to confirm the original booking’s status</td><td>One active original and no new order. The reviewer had no access to this final state</td></tr></tbody></table><p><img src="'+l+'" alt="Same approved price, with three different review decisions based on cancellation evidence"></p><p>Both reviewers who faced an unknown cancellation explained why they waited. <strong>The old receipt established that the booking had been committed. The empty list could not establish that it had been cancelled.</strong> They left the exact booking and request references for follow-up, and their tasks stayed open. Across all six cases, every ledger ended with exactly one active order. Only the two confirmed cancellations led to a new write. The study measured behavior and order states in a synthetic service. Payments, refunds, and final business acceptance were outside its scope.</p><h2 id="the-next-worker-needs-two-answers" tabindex="-1">The next worker needs two answers <a class="header-anchor" href="#the-next-worker-needs-two-answers" aria-label="Permalink to &quot;The next worker needs two answers&quot;">​</a></h2><p><strong>The price change establishes the terms the team can now book under. The provider’s query for the original request establishes whether the old booking still counts.</strong> A worker needs both pieces of evidence to decide whether to keep the booking, replace it, or keep investigating. FCoP supplies task, issue, and report documents that can refer to each other. CodeFlowMu persists them and records whether a report was formally submitted. The agent consults the evidence, makes the business decision, and records its reasons so another worker can check them against fresh provider evidence.</p><p>One timing question remains. Suppose the provider says the cancellation request was received and the reviewer decides to wait. The provider could then complete or reject it during the handoff. A follow-up can delay the final response until the next shift and test whether a fresh agent finds <strong>the very same cancellation request</strong> in the follow-up record and avoids a new booking until the outcome is known.</p><p><a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-11-27-receipt-binding" target="_blank" rel="noreferrer">Experiment notes on GitHub</a> · <a href="/joinwell52/assets/receipt-binding-20261127/reprice-results.json">Tool traces for the six follow-up cases</a> · <a href="/joinwell52/assets/receipt-binding-20261127/receipt-results.json">Tool traces for the initial six cases</a></p>',25))])}const y=n(c,[["render",p]]);export{b as __pageData,y as default};
